router.post('/generate', async function (req, res) {
    if (!req.body) return res.sendStatus(400);

    // virtual-companion bridge hook (patch st-novel-vc-guard; W13 unvalidated exit)
    const vcBridge = globalThis[Symbol.for('virtual-companion.bridge')];
    if (vcBridge) {
        await vcBridge.guardUnmanagedGeneration(req, res);
        return;
    }

    const api_key_novel = readSecret(req.user.directories, SECRET_KEYS.NOVEL);
